'use client';

/**
 * Application preparation panel.
 *
 * One job, one action: build the material this application actually needs. The
 * panel is deliberately explicit about three things:
 *
 *  - what will be produced and why (the deterministic plan),
 *  - what already exists, so nothing is regenerated by accident,
 *  - the state of every independent task, including failures and retries.
 *
 * While a run is active there is exactly one primary action (Continue) plus a
 * Stop control. The "start" action is hidden, because starting a second run
 * while one is in progress was never meaningful and made the old two-button
 * layout look broken.
 */

import Link from 'next/link';
import { useCallback, useEffect, useRef, useState } from 'react';
import {
  AlertCircle,
  ArrowRight,
  CheckCircle2,
  Circle,
  FileText,
  Info,
  Loader,
  RefreshCw,
  Sparkles,
  Square,
} from 'lucide-react';
import { BrandLoader } from '@/components/shared/brand-loader';

import type {
  PreparationPlan,
  PreparationRunSnapshot,
  PreparationStatus,
  PreparationTaskSnapshot,
  PreparationTaskType,
} from '@/lib/application-preparation/types';

const RECOMMENDATION_STYLES: Record<string, string> = {
  REQUIRED: 'bg-warn/15 text-warn-text border-warn/30',
  RECOMMENDED: 'bg-accent/15 text-accent-text border-accent/30',
  OPTIONAL: 'bg-surface-sunken text-muted border-line',
  NOT_NEEDED: 'bg-surface-sunken text-muted border-line',
};

const STATUS_STYLES: Record<string, string> = {
  COMPLETED: 'text-success-text',
  RUNNING: 'text-accent-text',
  FAILED: 'text-danger-text',
  SKIPPED: 'text-warn-text',
  PENDING: 'text-muted',
  CANCELLED: 'text-muted',
};

function taskIcon(task: PreparationTaskSnapshot) {
  if (task.status === 'COMPLETED') return <CheckCircle2 className="h-4 w-4 shrink-0 text-success-text" />;
  if (task.status === 'RUNNING') return <Loader className="h-4 w-4 shrink-0 animate-spin text-accent-text" />;
  if (task.status === 'FAILED') return <AlertCircle className="h-4 w-4 shrink-0 text-danger-text" />;
  if (task.status === 'SKIPPED') return <Info className="h-4 w-4 shrink-0 text-warn-text" />;
  return <Circle className="h-4 w-4 shrink-0 text-muted" />;
}

function runStatusLabel(status: PreparationRunSnapshot['status']): string {
  switch (status) {
    case 'QUEUED':
      return 'Ready to continue';
    case 'RUNNING':
      return 'Preparing…';
    case 'COMPLETED':
      return 'All materials ready';
    case 'PARTIALLY_COMPLETED':
      return 'Some materials need attention';
    case 'FAILED':
      return 'Preparation failed';
    case 'CANCELLED':
      return 'Stopped';
  }
}

export function PreparationPanel({ jobId }: { jobId: string }) {
  const [status, setStatus] = useState<PreparationStatus | null>(null);
  const [run, setRun] = useState<PreparationRunSnapshot | null>(null);
  const [selected, setSelected] = useState<PreparationTaskType[]>([]);
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);
  const [advancing, setAdvancing] = useState(false);
  const [cancelling, setCancelling] = useState(false);
  const [retryingTaskId, setRetryingTaskId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const mounted = useRef(true);
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  const applyRun = useCallback((nextRun: PreparationRunSnapshot) => {
    setRun(nextRun);
    setStatus((current) => (current ? { ...current, run: nextRun } : current));
  }, []);

  const applyStatus = useCallback((next: PreparationStatus) => {
    setStatus(next);
    setRun(next.run);
    const defaults = next.plan.items
      .filter((item) => item.available && item.selectedByDefault)
      .map((item) => item.type);

    // A plan can legitimately have no pre-selected items (for example, when
    // every available item already exists). Leaving the selection empty would
    // make the primary button permanently disabled, so fall back to the first
    // available item so the user can still act with one click.
    const fallback = next.plan.items
      .filter((item) => item.available)
      .map((item) => item.type)
      .slice(0, 1);
    const initial = defaults.length > 0 ? defaults : fallback;

    setSelected(
      next.run && !next.run.terminal
        ? (next.run.requestedTasks as PreparationTaskType[])
        : initial,
    );
  }, []);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`/api/jobs/${encodeURIComponent(jobId)}/preparation`, {
        cache: 'no-store',
      });
      const payload = await response.json().catch(() => null);
      if (!mounted.current) return;
      if (!response.ok) {
        setError(payload?.error?.message ?? 'Could not load preparation options.');
        return;
      }
      applyStatus(payload as PreparationStatus);
    } catch {
      if (mounted.current) setError('Could not load preparation options.');
    } finally {
      if (mounted.current) setLoading(false);
    }
  }, [applyStatus, jobId]);

  useEffect(() => {
    void load();
  }, [load]);

  const plan: PreparationPlan | null = status?.plan ?? null;
  const maxTasks = plan?.limits.maxTasksPerRun ?? 4;

  const refreshRun = useCallback(
    async (runId: string) => {
      try {
        const response = await fetch(
          `/api/preparation/runs/${encodeURIComponent(runId)}`,
          { cache: 'no-store' },
        );
        if (!response.ok) return;
        const payload = await response.json().catch(() => null);
        const nextRun = payload?.run as PreparationRunSnapshot | undefined;
        if (mounted.current && nextRun) applyRun(nextRun);
      } catch {
        // Polling is best-effort. The next tick or an explicit action retries.
      }
    },
    [applyRun],
  );

  // While a run is active, poll the durable state. This is what makes a task
  // that finished in another tab (or was reclaimed after an interrupted
  // function) appear without the user pressing anything.
  const runId = run?.id ?? null;
  const runTerminal = run?.terminal ?? true;
  useEffect(() => {
    if (!runId || runTerminal) return;
    const timer = window.setInterval(() => {
      if (document.visibilityState === 'hidden') return;
      void refreshRun(runId);
    }, 4_000);
    return () => window.clearInterval(timer);
  }, [runId, runTerminal, refreshRun]);

  function toggle(type: PreparationTaskType) {
    setError(null);
    setNotice(null);
    setSelected((current) => {
      if (current.includes(type)) return current.filter((entry) => entry !== type);
      if (current.length >= maxTasks) {
        setNotice(`You can prepare up to ${maxTasks} materials in one run.`);
        return current;
      }
      return [...current, type];
    });
  }

  /**
   * Execute tasks one advance call at a time. Each call is a separate request,
   * so a refresh between calls loses only the step in flight — everything
   * already recorded stays recorded.
   *
   * `singleStep` is used by "Retry this step": it must not silently continue
   * into sibling tasks and spend credits the user did not ask for.
   */
  const advance = useCallback(
    async (targetRunId: string, singleStep = false) => {
      setAdvancing(true);
      setError(null);
      setNotice(null);
      try {
        const iterations = singleStep ? 1 : 8;
        for (let iteration = 0; iteration < iterations; iteration += 1) {
          const response = await fetch(
            `/api/preparation/runs/${encodeURIComponent(targetRunId)}/advance`,
            {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ maxTasks: 1 }),
            },
          );
          const payload = await response.json().catch(() => null);
          if (!mounted.current) return;
          if (!response.ok) {
            if (response.status === 409) {
              setNotice(
                payload?.error?.message ??
                  'This preparation run was stopped. Retry a step or start again.',
              );
              await refreshRun(targetRunId);
              return;
            }
            setError(
              payload?.error?.message ??
                'Preparation could not continue. Your finished materials are safe.',
            );
            return;
          }

          const nextRun = payload?.run as PreparationRunSnapshot;
          applyRun(nextRun);

          if (!payload?.executed) {
            if (payload?.retryScheduled) {
              setNotice(
                'A step did not finish and can be retried below. Finished materials are saved.',
              );
            }
            return;
          }
          if (nextRun.terminal) return;
          if (payload?.retryScheduled) {
            setNotice(
              'A step did not finish. Finished materials are safe — retry that step below, or press Continue preparation.',
            );
            return;
          }
        }
      } catch {
        if (mounted.current) {
          setError(
            'Preparation was interrupted. Press Continue preparation to resume; finished materials are safe.',
          );
        }
      } finally {
        if (mounted.current) setAdvancing(false);
      }
    },
    [applyRun, refreshRun],
  );

  async function prepare() {
    if (!plan) return;
    setCreating(true);
    setError(null);
    setNotice(null);
    try {
      const response = await fetch(`/api/jobs/${encodeURIComponent(jobId)}/preparation`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tasks: selected }),
      });
      const payload = await response.json().catch(() => null);
      if (!mounted.current) return;
      if (!response.ok) {
        setError(payload?.error?.message ?? 'Preparation could not start.');
        return;
      }
      const nextRun = payload.run as PreparationRunSnapshot;
      applyRun(nextRun);
      if (nextRun.terminal) {
        setNotice('Everything in this run was already prepared.');
        return;
      }
      await advance(nextRun.id);
    } catch {
      if (mounted.current) setError('Preparation could not start. Nothing was charged.');
    } finally {
      if (mounted.current) setCreating(false);
    }
  }

  async function resume() {
    if (!run) return;
    await advance(run.id);
  }

  async function stop() {
    if (!run) return;
    setCancelling(true);
    setError(null);
    setNotice(null);
    try {
      const response = await fetch(
        `/api/preparation/runs/${encodeURIComponent(run.id)}/cancel`,
        { method: 'POST' },
      );
      const payload = await response.json().catch(() => null);
      if (!mounted.current) return;
      if (!response.ok) {
        setError(payload?.error?.message ?? 'Preparation could not be stopped.');
        return;
      }
      applyRun(payload.run as PreparationRunSnapshot);
      setNotice(
        'Preparation stopped. Anything already finished is saved; retry a single step below or prepare again.',
      );
    } catch {
      if (mounted.current) setError('Preparation could not be stopped. Please try again.');
    } finally {
      if (mounted.current) setCancelling(false);
    }
  }

  async function retryTask(taskId: string) {
    if (!run) return;
    setRetryingTaskId(taskId);
    setError(null);
    setNotice(null);
    try {
      const response = await fetch(
        `/api/preparation/runs/${encodeURIComponent(run.id)}/tasks/${encodeURIComponent(taskId)}/retry`,
        { method: 'POST' },
      );
      const payload = await response.json().catch(() => null);
      if (!mounted.current) return;
      if (!response.ok) {
        setError(payload?.error?.message ?? 'That step could not be restarted.');
        return;
      }

      const nextRun = payload.run as PreparationRunSnapshot;
      applyRun(nextRun);
      await advance(nextRun.id, true);
    } catch {
      if (mounted.current) setError('That step could not be restarted.');
    } finally {
      if (mounted.current) setRetryingTaskId(null);
    }
  }

  if (loading) {
    return <BrandLoader variant="inline" message="Loading preparation options…" className="card-pad" />;
  }

  if (error && !plan) {
    return (
      <div className="card-pad space-y-3">
        <div className="flex items-start gap-2 text-sm text-danger-text">
          <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" />
          <span>{error}</span>
        </div>
        <button type="button" className="btn-secondary gap-1.5 text-sm" onClick={() => void load()}>
          <RefreshCw className="h-3.5 w-3.5" /> Try again
        </button>
      </div>
    );
  }

  if (!plan) return null;

  const runInProgress = Boolean(run && !run.terminal);
  const busy = creating || advancing || cancelling || retryingTaskId !== null;
  const canStart =
    plan.canPrepare && selected.length > 0 && !busy && !runInProgress;
  const completedCount = run?.tasks.filter((task) => task.status === 'COMPLETED').length ?? 0;
  const disabledReason = !plan.canPrepare
    ? plan.blockers[0] ?? 'This application is not ready for preparation yet.'
    : selected.length === 0
      ? 'Select at least one material to prepare.'
      : null;

  return (
    <section className="card-pad space-y-5">
      <div className="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between">
        <div className="min-w-0">
          <h2 className="flex items-center gap-2 text-lg font-semibold text-ink">
            <Sparkles className="h-4 w-4 text-accent-text" />
            Application preparation
          </h2>
          <p className="mt-1 max-w-2xl text-sm leading-6 text-muted">
            Build the materials this application needs. Each item runs independently, so a slow or
            failed step never discards work that already succeeded.
          </p>
        </div>
        {run ? (
          <span className="shrink-0 rounded-full border border-line px-3 py-1 text-xs font-medium text-muted">
            {runStatusLabel(run.status)}
            {run.tasks.length > 0 ? ` · ${completedCount}/${run.tasks.length}` : ''}
          </span>
        ) : null}
      </div>

      <div className="rounded-xl border border-line bg-surface-sunken px-4 py-3 text-sm">
        <span className="text-muted">Starting point: </span>
        {plan.sourceResume.kind === 'STRUCTURED_RESUME' && plan.sourceResume.resumeId ? (
          <Link
            href={`/resumes/${plan.sourceResume.resumeId}`}
            className="font-medium text-accent-text hover:underline"
          >
            {plan.sourceResume.name}
          </Link>
        ) : (
          <span className="font-medium text-ink">
            {plan.sourceResume.kind === 'PROFILE' ? 'Your confirmed career profile' : 'Nothing available yet'}
          </span>
        )}
        <span className="block text-xs leading-5 text-muted">{plan.sourceResume.reason}</span>
      </div>

      {plan.blockers.length > 0 ? (
        <div className="space-y-1 rounded-xl border border-warn/30 bg-warn/10 px-4 py-3 text-sm text-warn-text">
          {plan.blockers.map((blocker) => (
            <p key={blocker} className="flex items-start gap-2">
              <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" />
              <span>{blocker}</span>
            </p>
          ))}
        </div>
      ) : null}

      <div className="grid gap-3 md:grid-cols-2">
        {plan.items.map((item) => {
          const isSelected = selected.includes(item.type);
          const disabled = !item.available || runInProgress || creating || advancing;
          return (
            <div
              key={item.type}
              className={`rounded-xl border px-4 py-3 transition-colors ${
                isSelected ? 'border-accent/40 bg-accent/[0.06]' : 'border-line bg-surface'
              }`}
            >
              <div className="flex items-start justify-between gap-3">
                <label className="flex min-w-0 cursor-pointer items-start gap-2.5">
                  <input
                    type="checkbox"
                    className="mt-0.5 h-4 w-4 shrink-0 accent-accent"
                    checked={isSelected}
                    disabled={disabled}
                    onChange={() => toggle(item.type)}
                  />
                  <span className="min-w-0">
                    <span className="block break-words text-sm font-medium text-ink">{item.label}</span>
                    <span className="mt-0.5 block text-xs leading-5 text-muted">{item.reason}</span>
                  </span>
                </label>
                <span
                  className={`shrink-0 rounded-full border px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide ${
                    RECOMMENDATION_STYLES[item.recommendation] ?? RECOMMENDATION_STYLES.OPTIONAL
                  }`}
                >
                  {item.available ? item.recommendation.toLowerCase() : 'not automated'}
                </span>
              </div>

              <div className="mt-2 flex flex-wrap items-center justify-between gap-2 border-t border-line pt-2 text-xs">
                <span className="text-muted">~{item.estimatedMinutes} min</span>
                {item.existing ? (
                  <Link
                    href={item.existing.href}
                    className="inline-flex items-center gap-1 font-medium text-accent-text hover:underline"
                  >
                    <FileText className="h-3 w-3" /> {item.existing.title}
                  </Link>
                ) : !item.available ? (
                  <span className="text-muted">Available from its own workspace</span>
                ) : null}
              </div>
            </div>
          );
        })}
      </div>

      {run && run.tasks.length > 0 ? (
        <div className="space-y-2 rounded-xl border border-line bg-surface-sunken px-4 py-3">
          {run.tasks.map((task) => {
            const canRetry = task.status === 'FAILED' || task.status === 'CANCELLED';
            return (
              <div key={task.id} className="flex flex-wrap items-start justify-between gap-2 text-sm">
                <div className="flex min-w-0 items-start gap-2">
                  {taskIcon(task)}
                  <div className="min-w-0">
                    <span className="break-words font-medium text-ink">{task.label}</span>
                    <span className={`ml-2 text-xs ${STATUS_STYLES[task.status] ?? 'text-muted'}`}>
                      {task.status.toLowerCase()}
                      {task.attempts > 0 ? ` · attempt ${task.attempts}/${task.maxAttempts}` : ''}
                    </span>
                    {task.errorMessage ? (
                      <p className="mt-0.5 text-xs leading-5 text-danger-text">{task.errorMessage}</p>
                    ) : null}
                  </div>
                </div>
                <div className="flex shrink-0 flex-wrap items-center gap-3">
                  {canRetry ? (
                    <button
                      type="button"
                      className="inline-flex items-center gap-1 text-xs font-medium text-accent-text hover:underline disabled:cursor-not-allowed disabled:opacity-50"
                      disabled={busy}
                      onClick={() => void retryTask(task.id)}
                    >
                      <RefreshCw
                        className={`h-3 w-3 ${retryingTaskId === task.id ? 'animate-spin' : ''}`}
                      />
                      {retryingTaskId === task.id ? 'Retrying…' : 'Retry this step'}
                    </button>
                  ) : null}
                  {task.resultHref ? (
                    <Link
                      href={task.resultHref}
                      className="inline-flex items-center gap-1 text-xs font-medium text-accent-text hover:underline"
                    >
                      Open <ArrowRight className="h-3 w-3" />
                    </Link>
                  ) : null}
                </div>
              </div>
            );
          })}
        </div>
      ) : null}

      {error ? (
        <p className="flex items-start gap-2 text-sm text-danger-text">
          <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" /> {error}
        </p>
      ) : null}
      {notice ? <p className="text-sm text-warn-text">{notice}</p> : null}

      <div className="flex flex-col gap-3 border-t border-line pt-4">
        {runInProgress ? (
          <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
            <div className="flex flex-wrap items-center gap-2">
              <button
                type="button"
                className="btn-primary gap-1.5 text-sm"
                disabled={advancing || cancelling}
                onClick={() => void resume()}
              >
                {advancing ? (
                  <>
                    <Loader className="h-3.5 w-3.5 animate-spin" /> Preparing…
                  </>
                ) : (
                  <>
                    <ArrowRight className="h-3.5 w-3.5" /> Continue preparation
                  </>
                )}
              </button>
              <button
                type="button"
                className="btn-secondary gap-1.5 text-sm text-danger-text"
                disabled={cancelling}
                onClick={() => void stop()}
              >
                {cancelling ? (
                  <>
                    <Loader className="h-3.5 w-3.5 animate-spin" /> Stopping…
                  </>
                ) : (
                  <>
                    <Square className="h-3.5 w-3.5" /> Stop preparation
                  </>
                )}
              </button>
            </div>
            <span className="text-xs text-muted">
              Stop cancels the run. Finished materials stay saved.
            </span>
          </div>
        ) : (
          <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
            <div className="flex flex-wrap items-center gap-2">
              <button
                type="button"
                className="btn-primary gap-1.5 text-sm"
                disabled={!canStart}
                title={disabledReason ?? ''}
                onClick={() => void prepare()}
              >
                {creating ? (
                  <>
                    <Loader className="h-3.5 w-3.5 animate-spin" /> Preparing…
                  </>
                ) : (
                  <>
                    <Sparkles className="h-3.5 w-3.5" />{' '}
                    {run ? 'Prepare again' : 'Prepare my application'}
                  </>
                )}
              </button>
              <span className="text-xs text-muted">
                {selected.length} of{' '}
                {plan.items.filter((item) => item.available).length} available{' '}
                {plan.items.filter((item) => item.available).length === 1 ? 'material' : 'materials'}{' '}
                selected
              </span>
            </div>
            {disabledReason ? (
              <span className="text-xs text-warn-text">{disabledReason}</span>
            ) : null}
          </div>
        )}

        <p className="text-xs leading-5 text-muted">
          Nothing is marked as applied. Submission and its evidence stay a separate, explicit step.
        </p>
      </div>
    </section>
  );
}
